"use client";

import { labelStyles } from "@/lib/brasa/utils/styles";
import { forwardRef, useId, useCallback, useState, type ChangeEvent } from "react";
import { maskPhone } from "@/lib/brasa/utils/masks";
import { validatePhone } from "@/lib/brasa/utils/validators";

export interface PhoneBRProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange" | "value"> {
  value?: string;
  onChange?: (value: string, raw: string) => void;
  onValidate?: (valid: boolean) => void;
  label?: string;
  error?: string;
}

export const PhoneBR = forwardRef<HTMLInputElement, PhoneBRProps>(
  (
    {
      className = "",
      value: controlledValue,
      onChange,
      onValidate,
      label = "Telefone",
      error,
      id,
      ...props
    },
    ref
  ) => {
    const [internalValue, setInternalValue] = useState("");

    const currentValue = controlledValue ?? internalValue;

    const handleChange = useCallback(
      (e: ChangeEvent<HTMLInputElement>) => {
        const masked = maskPhone(e.target.value);
        const raw = masked.replace(/\D/g, "");

        if (controlledValue === undefined) {
          setInternalValue(masked);
        }

        onChange?.(masked, raw);

        if (raw.length >= 10) {
          onValidate?.(validatePhone(raw));
        }
      },
      [controlledValue, onChange, onValidate]
    );

    const generatedId = useId();
    const inputId = id || generatedId;

    return (
      <div className="space-y-1.5">
        {label && (
          <label
            htmlFor={inputId}
            className={labelStyles}
          >
            {label}
          </label>
        )}
        <div className={`flex h-10 items-center rounded-[var(--brasa-radius-control,0.625rem)] border bg-[var(--brasa-surface,#fff)] transition-shadow focus-within:ring-[3px] ${
          error
            ? "border-red-300 focus-within:ring-red-400/40"
            : "border-[var(--brasa-border,#dfe4dc)] focus-within:border-[var(--brasa-primary,#285b43)] focus-within:ring-[var(--brasa-ring,#dce9df)] hover:border-[#b7c3b8]"
        }`}>
          <span className="flex items-center gap-1.5 border-r border-neutral-200 bg-[#f5f6f2] px-3.5 py-2 rounded-l-[var(--brasa-radius-control,0.625rem)]">
            <span className="text-sm">🇧🇷</span>
            <span className="text-[11px] font-semibold tracking-wide text-neutral-500">+55</span>
          </span>
          <input
            {...props}
          ref={ref}
            id={inputId}
            type="tel"
            inputMode="tel"
            placeholder="(00) 00000-0000"
            aria-invalid={!!error}
            aria-describedby={[props["aria-describedby"], error ? `${inputId}-error` : null].filter(Boolean).join(" ") || undefined}
            value={currentValue}
            onChange={handleChange}
            maxLength={15}
            className={`min-w-0 flex-1 bg-transparent px-3.5 py-2 font-mono text-sm text-neutral-900 placeholder:text-neutral-400 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50 ${className}`}
            />
        </div>
        {error && (
          <p id={`${inputId}-error`} className="text-xs font-medium text-red-600" role="alert">
            {error}
          </p>
        )}
      </div>
    );
  }
);

PhoneBR.displayName = "PhoneBR";

export function maskCPF(value: string): string {
  const digits = value.replace(/\D/g, "").slice(0, 11);
  return digits
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d{1,2})$/, "$1-$2");
}

export function maskCNPJ(value: string): string {
  const digits = value.replace(/\D/g, "").slice(0, 14);
  return digits
    .replace(/(\d{2})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1.$2")
    .replace(/(\d{3})(\d)/, "$1/$2")
    .replace(/(\d{4})(\d{1,2})$/, "$1-$2");
}

export function maskCEP(value: string): string {
  const digits = value.replace(/\D/g, "").slice(0, 8);
  return digits.replace(/(\d{5})(\d{1,3})$/, "$1-$2");
}

export function maskPhone(value: string): string {
  const digits = value.replace(/\D/g, "").slice(0, 11);
  if (digits.length <= 10) {
    return digits
      .replace(/(\d{2})(\d)/, "($1) $2")
      .replace(/(\d{4})(\d{1,4})$/, "$1-$2");
  }
  return digits
    .replace(/(\d{2})(\d)/, "($1) $2")
    .replace(/(\d{5})(\d{1,4})$/, "$1-$2");
}

export function maskBRL(value: string): string {
  const digits = value.replace(/\D/g, "");
  if (!digits) return "";
  const cents = parseInt(digits, 10);
  return (cents / 100).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

export function validateCPF(cpf: string): boolean {
  const digits = cpf.replace(/\D/g, "");
  if (digits.length !== 11) return false;
  if (/^(\d)\1{10}$/.test(digits)) return false;

  let sum = 0;
  for (let i = 0; i < 9; i++) sum += parseInt(digits[i]) * (10 - i);
  let check = 11 - (sum % 11);
  if (check >= 10) check = 0;
  if (parseInt(digits[9]) !== check) return false;

  sum = 0;
  for (let i = 0; i < 10; i++) sum += parseInt(digits[i]) * (11 - i);
  check = 11 - (sum % 11);
  if (check >= 10) check = 0;
  return parseInt(digits[10]) === check;
}

export function validateCNPJ(cnpj: string): boolean {
  const digits = cnpj.replace(/\D/g, "");
  if (digits.length !== 14) return false;
  if (/^(\d)\1{13}$/.test(digits)) return false;

  const weights1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
  const weights2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];

  let sum = 0;
  for (let i = 0; i < 12; i++) sum += parseInt(digits[i]) * weights1[i];
  let check = sum % 11 < 2 ? 0 : 11 - (sum % 11);
  if (parseInt(digits[12]) !== check) return false;

  sum = 0;
  for (let i = 0; i < 13; i++) sum += parseInt(digits[i]) * weights2[i];
  check = sum % 11 < 2 ? 0 : 11 - (sum % 11);
  return parseInt(digits[13]) === check;
}

export function validateCEP(cep: string): boolean {
  return /^\d{8}$/.test(cep.replace(/\D/g, ""));
}

export function validatePhone(phone: string): boolean {
  const digits = phone.replace(/\D/g, "");
  return digits.length === 10 || digits.length === 11;
}

/** Shared visual language. Fallbacks also work in copied components. */
export const controlStyles = "flex h-10 w-full min-w-0 rounded-[var(--brasa-radius-control,0.625rem)] border bg-[var(--brasa-surface,#fff)] px-3 py-2 text-sm text-[var(--brasa-foreground,#23352c)] shadow-[0_1px_2px_#182a1e05] transition-[border-color,box-shadow,background-color] duration-150 placeholder:text-[#8a938c] focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-[var(--brasa-ring,#dce9df)] disabled:cursor-not-allowed disabled:bg-[#f5f6f2] disabled:opacity-60 motion-reduce:transition-none";
export const controlBorder = "border-[var(--brasa-border,#dfe4dc)] hover:border-[#b7c3b8] focus-visible:border-[var(--brasa-primary,#285b43)]";
export const controlError = "border-red-400 focus-visible:border-red-500 focus-visible:ring-red-100";
export const labelStyles = "block text-[13px] font-medium leading-5 text-[var(--brasa-foreground,#23352c)]";
export const surfaceStyles = "rounded-[var(--brasa-radius-card,1rem)] border border-[var(--brasa-border,#dfe4dc)] bg-[var(--brasa-surface,#fff)] text-[var(--brasa-foreground,#23352c)]";
export const focusStyles = "focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-[var(--brasa-ring,#dce9df)] focus-visible:ring-offset-2 motion-reduce:transition-none";
